const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',folder:'M3 5h6l2 3h10v12H3Z',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 3a4 4 0 0 1 0 8 M22 21v-3a4 4 0 0 0-3-4',check:'M8 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V5a2 2 0 0 0-2-2h-3 M8 3h8v4H8Z M7 13l3 3 7-7',calendar:'M3 5h18v16H3Z M3 10h18 M7 2v6 M17 2v6',invoice:'M6 3h10l4 4v14H6Z M15 3v5h5 M10 12h6 M10 16h4',wallet:'M3 5h16v5H3Z M3 8v13h18V10h-6v6h6 M17 13h1',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',chart:'M3 20v-5 M8 20v-8 M13 20v-5 M18 20V9 M3 10l5-5 5 3 7-6 M16 2h4v4',note:'M5 3h14v15l-4 4H5Z M8 8h8 M8 12h6 M8 16h3',settings:'M9 3h6l1 3 3 1 2 5-2 2-1 4-4 3-3-2-4-1-3-4 2-3V7l3-1Z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',search:'m21 21-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 5v14 M5 12h14',right:'m9 5 7 7-7 7',left:'m15 5-7 7 7 7',arrow:'M4 12h16 m-6-6 6 6-6 6',more:'M4 12h.01 M12 12h.01 M20 12h.01',video:'M3 6h12v12H3Z m12 4 6-4v12l-6-4',close:'m6 6 12 12 M18 6 6 18',down:'m5 9 7 7 7-7',play:'m9 5 11 7-11 7Z',link:'m10 13 4-4 M8 16l-2 2a4 4 0 0 1-6-6l4-4 M16 8l2-2a4 4 0 0 1 6 6l-4 4',mail:'M3 5h18v14H3Z m0 0 9 8 9-8'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${window.HUGEICONS?.[n]||`<path d="${paths[n]||paths.folder}"/>`}</svg>`;
const navs=['Today','Projects','Clients','Tasks','Calendar','Invoices','Expenses','Budget','Investments','Notes','Meetings'];const icons=['home','folder','users','check','calendar','invoice','wallet','clock','chart','note','calendar'];
const seed={tasks:[['Review homepage design','Pixel Studio','Website Redesign','High',true],['Client feedback revisions','Nova Brands','Brand Identity','Medium',true],['Prepare invoice','Nova Brands','INV-004','Medium',false],['Research motion ideas','Personal','Exploration','Low',false]],projects:[['Website Redesign','Pixel Studio',70,'2 May','pixel'],['Brand Identity','Nova Brands',40,'12 May','nova'],['Mobile App UI','Square One',20,'28 May','mobile']],clients:[['Pixel Studio','2 projects','₹1,20,000','pixel'],['Nova Brands','1 project','₹80,000','nova'],['Square One','1 project','₹60,000',''],['Bright Labs','Closed','₹45,000','']],meetings:[['10:00 AM','Design review','Pixel Studio','#5a9cde'],['12:30 PM','Project kickoff','Nova Brands','#65bf86'],['3:00 PM','Check-in call','Square One','#a486ee'],['5:00 PM','Weekly planning','Personal','#587dff']],invoices:[['INV-004','Nova Brands','₹80,000','Paid','12 Apr'],['INV-003','Square One','₹60,000','Sent','08 Apr'],['INV-002','Pixel Studio','₹1,20,000','Overdue','28 Mar']],expenses:[['Software','₹8,000','33%','#80a8ff'],['Equipment','₹6,500','27%','#7acba0'],['Marketing','₹5,000','20%','#fac3a5'],['Others','₹5,000','20%','#ffa3a6']],notes:[],investments:[['Mutual Funds','₹2,00,000','10.2%'],['Stocks','₹1,00,000','5.6%'],['Crypto','₹50,000','12.1%']],budgets:[]};
let state;try{state=JSON.parse(localStorage.getItem('mono-v1'))}catch{}if(!state)state={current:'demo',workspaces:[{id:'demo',name:'Personal Workspace',data:structuredClone(seed)}]};let page='Today',quickType='Task',priority='High',dayOffset=0,timerRunning=false,timerSeconds=0,timerCategory='Design';let data=()=>state.workspaces.find(w=>w.id===state.current).data;const save=()=>{try{localStorage.setItem('mono-v1',JSON.stringify(state,(key,value)=>key==='url'&&typeof value==='string'&&value.startsWith('blob:')?undefined:value))}catch(error){toast('Unable to save: browser storage is full. Remove unused attachments or records.');throw error}};const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const action=(label,fn,cls='')=>`<button class="${cls}" onclick="${fn}">${label}</button>`;const head=(t,p)=>`<div class="panel-head"><h2>${t}</h2>${action('View all '+icon('arrow'),`navigate('${p}')`,'text-button')}</div>`;const brand=(type,text)=>`<span class="brand ${type}">${type==='pixel'?'':esc(text||'N')}</span>`;
function render(){const ws=state.workspaces.find(w=>w.id===state.current);document.getElementById('app').innerHTML=`<aside><div class="logo">mono.</div><label class="search">${icon('search')}<input placeholder="Search..." aria-label="Search workspace" oninput="searchAll(this.value)"><small>⌘ K</small></label><nav>${navs.map((n,i)=>action(icon(icons[i])+`<span>${n}</span>`,`navigate('${n}')`,page===n?'active':'')).join('')}</nav><div class="aside-bottom">${action(icon('settings')+'<span>Settings</span>',"workspaceMenu()",'settings')}<button class="workspace" onclick="workspaceMenu()"><span class="avatar">RY</span><span class="row-title">Designer<small>${esc(ws.name)}</small></span></button></div></aside><div class="shell">${page==='Today'?dashboard():listing()}</div><div id="overlay"></div>`;}
function stats(items){return `<div class="stats">${items.map((s,i)=>`<div class="stat"><span class="stat-icon">${icon(s[0])}</span><div><strong>${s[1]}</strong><p>${s[2]}</p><small class="${s[4]||''}">${s[3]}</small>${i===0?'<div class="progress"><i style="width:40%"></i></div>':''}</div>${i===3?`<div class="bars">${[8,5,11,9,14,21].map(h=>`<i style="height:${h}px"></i>`).join('')}</div>`:''}</div>`).join('')}</div>`}
function taskRows(){return data().tasks.map((t,i)=>`<div class="task-row"><input class="check" type="checkbox" aria-label="Complete ${esc(t[0])}" ${t[4]?'checked':''} onchange="toggleTask(${i},this.checked)"><div class="row-title" onclick="detail('Task',${i})" style="cursor:pointer"><strong>${esc(t[0])}</strong><small>${esc(t[1])} ・ ${esc(t[2])}</small></div><span class="badge ${t[3].toLowerCase()}">${t[3]}</span><span class="due">Today</span>${action(icon('right'),`detail('Task',${i})`,'chevron')}</div>`).join('')||'<p class="empty">No tasks yet</p>'}
function dashboard(){const d=data(),demo=state.current==='demo';return `<main><header class="heading"><p>Monday, 28 Apr 2025</p><h1>Good morning.</h1><p class="subtitle">Here’s what’s happening with your work.</p>${action(icon('plus')+'Quick Add','openQuick()','primary')}</header>${stats([['check',d.tasks.length,'Tasks today',`${d.tasks.filter(t=>t[4]).length} completed`],['folder',d.projects.length,'Active projects',demo?'1 due this week':'No deadlines'],['wallet',demo?'₹2,40,000':'₹0','Total income (YTD)',demo?'↑ 12%':'','green'],['clock',demo?'12h 30m':'0h 00m','Total work time','This week']])}<div class="main-grid"><section class="panel tasks">${head('Today’s tasks','Tasks')}${taskRows()}</section><section class="panel meetings">${head('Upcoming meetings','Meetings')}${d.meetings.map((m,i)=>`<div class="meeting"><span class="dot" style="background:${m[3]}"></span><time>${m[0]}</time><div class="row-title"><strong>${esc(m[1])}</strong><small>${esc(m[2])}</small></div>${action(icon(i===3?'note':'video'),`detail('Meeting',${i})`)}</div>`).join('')||'<p class="empty">No meetings scheduled</p>'}</section><section class="panel projects">${head('Active projects','Projects')}${d.projects.map((p,i)=>`<div class="project">${brand(p[4],p[0][0])}<div class="row-title"><strong>${esc(p[0])}</strong><small>${esc(p[1])}</small></div><div class="project-progress">${p[2]}%<div class="progress"><i style="width:${p[2]}%"></i></div></div><span class="due">Due ${p[3]}</span>${action(icon('more'),`detail('Project',${i})`,'more')}</div>`).join('')||'<p class="empty">No projects yet</p>'}</section><section class="panel">${head('Recent clients','Clients')}${d.clients.map((c,i)=>`<div class="client">${brand(c[3],c[0][0])}<div class="row-title"><strong>${esc(c[0])}</strong><small>${c[1]} ・ ${c[2]}</small></div>${action(icon('right'),`detail('Client',${i})`,'chevron')}</div>`).join('')||'<p class="empty">No clients yet</p>'}</section><div class="bottom-grid"><section class="panel">${head('Invoices','Invoices')}${d.invoices.map((v,i)=>`<div class="invoice" onclick="detail('Invoice',${i})" style="cursor:pointer"><span>${v[0]}</span><small>${v[1]}</small><span>${v[2]}</span><span class="badge ${v[3]==='Paid'?'paid':v[3]==='Sent'?'sent':'medium'}">${v[3]}</span><small>${v[4]}</small></div>`).join('')||'<p>No invoices yet</p>'}</section><section class="panel expenses"><div class="panel-head"><h2>Expenses</h2><select aria-label="Expense period" onchange="toast('Showing '+this.value.toLowerCase()+' expenses')"><option>This month</option><option>This year</option></select></div><div class="expense-body"><div class="donut"><div class="donut-center"><strong>${demo?'₹24,500':'₹0'}</strong><small>Total</small></div></div><div class="legend">${d.expenses.map(e=>`<div><span class="dot" style="background:${e[3]}"></span>${esc(e[0])}<b>${e[1]}</b><small>${e[2]}</small></div>`).join('')}</div></div></section></div></div></main><div class="right">${calendar()}${timer()}<section class="panel investments">${head('Investments','Investments')}<div class="investment-total"><strong>${demo?'₹3,50,000':'₹0'}</strong><small class="green">${demo?'↑ 8.4%':''}</small><svg class="spark" viewBox="0 0 150 45"><path d="M1 37 12 30 22 30 31 24 43 25 53 15 64 19 76 16 87 10 99 15 110 12 122 5 134 7 149 2" stroke="#24b778"/></svg></div>${d.investments.map((v,i)=>`<div class="investment-row"><span>${['◉','◉','◉'][i%3]} &nbsp; ${esc(v[0])}</span><span>${v[1]}</span><span class="green">↑ ${v[2]}</span></div>`).join('')}</section></div>`}
function calendar(){let dt=new Date(2025,3,28+dayOffset);return `<section class="panel day-calendar"><div class="calendar-toolbar"><strong>${dt.toLocaleString('en',{month:'long',year:'numeric'})}</strong>${action(icon('left'),'changeDay(-7)')}${action(icon('right'),'changeDay(7)')}${action('Today','changeDay(0,true)')}</div><div class="week-strip">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((w,i)=>{let v=new Date(2025,3,28+dayOffset+i);return `<div><small>${w}</small><button onclick="selectDay(this)" class="${i===0?'selected':''}">${v.getDate()}</button></div>`}).join('')}</div><div class="timeline">${Array.from({length:10},(_,i)=>`<div class="hour" style="top:${i*41}px"><span>${i+9<12?i+9+' AM':i===3?'12 PM':i-3+' PM'}</span></div>`).join('')}${state.current==='demo'?[['Design review','Pixel Studio',33,'blue'],['Project kickoff','Nova Brands',123,'green-event'],['Check-in call','Square One',245,'purple'],['Weekly planning','Personal',328,'gray']].map((e,i)=>`<button class="event ${e[3]}" style="top:${e[2]}px" onclick="detail('Meeting',${i})">${e[0]}<small>${e[1]}</small></button>`).join(''):''}</div></section>`}
function timer(){return `<section class="panel timer"><div class="panel-head"><h2>Time tracking</h2><select aria-label="Time tracking period"><option>Today</option><option>This week</option></select></div><div class="timer-display">${action(timerRunning?'Ⅱ':'▶','toggleTimer()','play')}<div><strong id="timer-value">${formatTime()}</strong><small>${timerRunning?'Tracking '+timerCategory.toLowerCase():'No active timer'}</small></div></div><div class="timer-categories">${['Design','Meeting','Research'].map(c=>action(c,`setCategory('${c}')`,c===timerCategory?'active':'')).join('')}${action('•••',"toast('Choose Design, Meeting, or Research')")}</div></section>`}
function listing(){let key={Projects:'projects',Clients:'clients',Tasks:'tasks',Meetings:'meetings',Invoices:'invoices',Expenses:'expenses',Investments:'investments',Notes:'notes',Budget:'budgets'}[page];if(page==='Calendar')return `<main class="screen-list"><header class="heading"><p>Calendar</p><h1>April 2025</h1><p class="subtitle">Plan your meetings, deadlines and stay on top of your schedule.</p>${action('+ New Event',"openQuick('Meeting')",'primary')}</header>${calendar()}</main>`;const type={Projects:'Project',Clients:'Client',Tasks:'Task',Meetings:'Meeting',Invoices:'Invoice',Expenses:'Expense',Investments:'Investment',Notes:'Note',Budget:'Budget'}[page];return `<main class="screen-list"><header class="heading"><p>${page}</p><h1>${page==='Budget'?'Monthly Budget':'All '+page}</h1><p class="subtitle">${{Projects:'Plan, track and deliver your work.',Clients:'Manage your clients, track projects, invoices and build long-term relationships.',Tasks:'Stay focused and get your work done.',Meetings:'Plan, track and follow up on important meetings.',Notes:'Capture ideas, research, and important information.'}[page]||'Track and manage your '+page.toLowerCase()+'.'}</p>${action('+ New '+type,`openQuick('${type}')`,'primary')}</header><section class="panel"><label class="search" style="background:white;border:1px solid #eee;margin-bottom:20px">${icon('search')}<input placeholder="Search ${page.toLowerCase()}..." oninput="filterRows(this.value)"></label><div id="list-rows">${page==='Tasks'?taskRows():data()[key].map((r,i)=>`<div class="task-row filter-row" onclick="detail('${type}',${i})" style="cursor:pointer">${brand(r[4]||'',r[0][0])}<div class="row-title"><strong>${esc(r[0])}</strong><small>${esc(r[1]||'')}</small></div><span>${esc(r[2]||'')}</span>${action(icon('more'),`event.stopPropagation();detail('${type}',${i})`,'more')}</div>`).join('')||`<div class="empty">No ${page.toLowerCase()} yet. Create your first ${type.toLowerCase()}.</div>`}</div></section></main>`}
function navigate(p){page=p;render()}function toggleTask(i,v){data().tasks[i][4]=v;save();if(page==='Today'){const p=window.scrollY;render();window.scrollTo(0,p)}}function changeDay(n,reset){dayOffset=reset?0:dayOffset+n;render()}function selectDay(el){document.querySelectorAll('.week-strip button').forEach(b=>b.classList.remove('selected'));el.classList.add('selected')}function formatTime(){return Math.floor(timerSeconds/3600)+'h '+String(Math.floor(timerSeconds/60)%60).padStart(2,'0')+'m'}function toggleTimer(){timerRunning=!timerRunning;render()}function setCategory(c){timerCategory=c;render()}setInterval(()=>{if(timerRunning){timerSeconds++;let el=document.getElementById('timer-value');if(el)el.textContent=formatTime()}},1000);function toast(s){let el=document.createElement('div');el.className='toast';el.textContent=s;document.body.appendChild(el);setTimeout(()=>el.remove(),3000)}
function workspaceMenu(){let old=document.querySelector('.workspace-menu');if(old){old.remove();return}let el=document.createElement('div');el.className='workspace-menu';el.innerHTML=`<b style="display:block;padding:8px">Workspaces</b>${state.workspaces.map(w=>action((w.id===state.current?'✓ ':'')+esc(w.name),`switchWorkspace('${w.id}')`)).join('')}<hr style="border:0;border-top:1px solid #eee"><form onsubmit="createWorkspace(event)"><input name="workspaceName" placeholder="New workspace name" required maxlength="60" aria-label="New workspace name"><button class="primary" type="submit">+ Create workspace</button></form>`;document.body.appendChild(el)}function switchWorkspace(id){state.current=id;save();document.querySelector('.workspace-menu')?.remove();render()}function createWorkspace(e){e.preventDefault();let name=new FormData(e.target).get('workspaceName').trim();if(!name)return;let id='ws-'+Date.now();let empty=Object.fromEntries(Object.keys(seed).map(k=>[k,[]]));state.workspaces.push({id,name,data:empty});switchWorkspace(id);toast('Workspace created')}
function openQuick(type='Task'){quickType=type;let ov=document.getElementById('overlay');ov.innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeOverlay()"><section class="modal" role="dialog" aria-modal="true" aria-label="Quick Add"><header><div><h2>Quick Add</h2><p>Add a new item to your workspace.</p></div>${action(icon('close'),'closeOverlay()')}</header><div class="quick-layout"><div class="quick-nav">${['Task','Project','Client','Meeting','Note','Invoice','Expense','Budget','Investment'].map((t,i)=>action(icon(['check','folder','users','calendar','note','invoice','wallet','clock','chart'][i])+t,`openQuick('${t}')`,t===type?'active':'')).join('')}</div><form id="quick-form" class="quick-form" onsubmit="submitQuick(event)"><h3>Add ${type}</h3><p>${{Task:'Create a new task and get things done.',Project:'Create a new project to organize your work.',Meeting:'Schedule a meeting with clients, advisors or your team.'}[type]||'Add a new '+type.toLowerCase()+' to your workspace.'}</p><label class="field">${type==='Project'?'Project name':'Title'} <span style="color:red">*</span><input name="title" required maxlength="120" placeholder="${type==='Task'?'e.g. Review homepage design':'Enter '+type.toLowerCase()+' title'}"></label><label class="field">Description (optional)<textarea name="description" maxlength="500" placeholder="Add more details, notes or links..."></textarea></label><div class="field-row"><label class="field">${type==='Meeting'?'Date':'Project (optional)'}${type==='Meeting'?'<input name="date" type="date" value="2025-04-18">':`<select name="project"><option value="">Select project</option>${data().projects.map(p=>`<option>${esc(p[0])}</option>`).join('')}</select>`}</label><label class="field">Client (optional)<select name="client"><option value="">Select client</option>${data().clients.map(c=>`<option>${esc(c[0])}</option>`).join('')}</select></label></div>${['Expense','Invoice','Investment','Budget'].includes(type)?'<label class="field">Amount (₹)<input name="amount" type="number" min="0" step="0.01" required placeholder="0.00"></label>':`<div class="field-row"><div class="field">Priority<div class="priority-options">${['High','Medium','Low'].map(p=>`<button type="button" class="badge ${p.toLowerCase()} ${priority===p?'selected':''}" onclick="priority='${p}';document.querySelectorAll('.priority-options button').forEach(b=>b.classList.remove('selected'));this.classList.add('selected')">${p}</button>`).join('')}</div></div><label class="field">Due date (optional)<input name="date" type="date"></label></div>`}<label class="field">Tags (optional)<input name="tags" placeholder="Add tag"></label></form></div><footer><label><input type="checkbox" id="create-another"> Create another after saving</label>${action('Cancel','closeOverlay()')}<button class="primary" type="submit" form="quick-form">Add ${type}</button></footer></section></div>`;ov.querySelector('[name=title]').focus()}
function closeOverlay(){document.getElementById('overlay').innerHTML=''}function submitQuick(e){e.preventDefault();const f=new FormData(e.target),title=f.get('title').trim();if(!title)return;const client=f.get('client')||'Personal',project=f.get('project')||'—',amount='₹'+Number(f.get('amount')||0).toLocaleString('en-IN'),d=data();if(quickType==='Task')d.tasks.push([title,client,project,priority,false]);if(quickType==='Project')d.projects.push([title,client,0,'—','']);if(quickType==='Client')d.clients.push([title,'0 projects','₹0','']);if(quickType==='Meeting')d.meetings.push(['11:00 AM',title,client,'#5a9cde']);if(quickType==='Invoice')d.invoices.push(['INV-'+String(d.invoices.length+1).padStart(3,'0'),client,amount,'Draft','28 Apr']);if(quickType==='Expense')d.expenses.push([title,amount,'','#80a8ff']);if(quickType==='Investment')d.investments.push([title,amount,'0%']);if(quickType==='Note')d.notes.push([title,f.get('description'),'28 Apr 2025']);if(quickType==='Budget')d.budgets.push([title,amount,'April 2025']);const another=document.getElementById('create-another').checked;save();render();if(another)openQuick(quickType);toast(quickType+' created successfully')}
function detail(type,i){const key={Task:'tasks',Project:'projects',Client:'clients',Meeting:'meetings',Invoice:'invoices',Expense:'expenses',Investment:'investments',Note:'notes',Budget:'budgets'}[type],r=data()[key]?.[i];if(!r)return;document.getElementById('overlay').innerHTML=`<section class="detail-backdrop" role="dialog" aria-label="${type} details">${action(icon('close'),'closeOverlay()','more')}<h2>${esc(type==='Meeting'?r[1]:r[0])}</h2><span class="badge sent">${type==='Task'?(r[4]?'Completed':'Todo'):type}</span>${r.slice(1,4).map((v,j)=>`<div class="detail-row"><span>${['Details','Project / value','Status / priority'][j]}</span><span>${esc(v)}</span></div>`).join('')}<h3>Description</h3><p>${type==='Task'?'Review the latest work and provide feedback on layout, copy and visuals.':'Details for this '+type.toLowerCase()+'.'}</p>${type==='Task'?action(r[4]?'Mark incomplete':'Mark complete',`toggleTask(${i},${!r[4]});closeOverlay()`,'primary'):''}<div style="margin-top:24px">${action('Delete '+type,`deleteRecord('${key}',${i})`)}</div></section>`}function deleteRecord(k,i){data()[k].splice(i,1);save();render();toast('Item deleted')}function filterRows(v){document.querySelectorAll('#list-rows>.task-row').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(v.toLowerCase())?'flex':'none')}function searchAll(v){if(!v)return;page='Tasks';render();const input=document.querySelector('#list-rows')?.previousElementSibling?.querySelector('input');if(input){input.value=v;filterRows(v);input.focus()}}document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeOverlay();document.querySelector('.workspace-menu')?.remove()}if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();openQuick()}});render();
